import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, it } from 'node:test';

/**
 * Incoming-call Android classes are generated by the config plugin, so keep
 * the credential handoff boundary covered without importing native code into
 * the TypeScript test graph.
 */
const SOURCE = readFileSync(
  resolve(process.cwd(), 'plugins/withNativeIncomingCallAndroid.cjs'),
  'utf8',
);
const CALL_ACTIONS_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/notifications/calls/callActions.ts'),
  'utf8',
);
const SESSION_CLEANUP_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/notifications/sessionCleanup.ts'),
  'utf8',
);
const CALL_LAUNCH_HANDLER_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/services/CallLaunchHandler.ts'),
  'utf8',
);
const CALL_LAUNCH_LIFECYCLE_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/services/callLaunchLifecycle.ts'),
  'utf8',
);
const CALL_DATA_MODULE_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/modules/CallNotificationDataModule.ts'),
  'utf8',
);
const IOS_CALL_KIT_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/services/CallKitService.ios.ts'),
  'utf8',
);
const ANDROID_CALL_KIT_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/services/CallKitService.android.ts'),
  'utf8',
);
const CALL_ACTIONS_SESSION_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/notifications/calls/callActions.ts'),
  'utf8',
);
const CALL_SETUP_SOURCE = readFileSync(
  resolve(process.cwd(), 'src/notifications/calls/callSetup.ts'),
  'utf8',
);

describe('Android incoming-call credential handoff policy', () => {
  it('does not place call credentials in notification intents', () => {
    assert.doesNotMatch(
      SOURCE,
      /putExtra\([^\n]*(?:token|serverUrl)|EXTRA_(?:TOKEN|SERVER_URL)/i,
      'call credentials must not be copied into notification or activity intents',
    );
  });

  it('does not persist call credentials in SharedPreferences', () => {
    assert.doesNotMatch(
      SOURCE,
      /putString\((?:KEY_TOKEN|KEY_SERVER_URL|["'](?:token|serverUrl)["'])/,
      'call credentials must not be written to CallNotificationData preferences',
    );
    assert.match(
      SOURCE,
      /remove\(LEGACY_TOKEN_KEY\)[\s\S]*remove\(LEGACY_SERVER_URL_KEY\)/,
      'credentials written by older versions must be retired',
    );
  });

  it('retains authenticated API credential recovery for answered calls', () => {
    assert.match(
      CALL_ACTIONS_SOURCE,
      /if \(payload\.token && payload\.serverUrl\)[\s\S]*?callService\.joinCall\(\{ callId: payload\.callId \}\)/,
      'answered calls must reacquire short-lived media credentials through the authenticated API',
    );
  });

  it('clears pending native call data during logout cleanup', () => {
    assert.doesNotMatch(
      SESSION_CLEANUP_SOURCE,
      /from ['"]@\/src\/services\/CallLaunchHandler['"];?/,
      'logout cleanup must not recreate the auth-context/call-service import cycle at startup',
    );
    assert.match(
      SESSION_CLEANUP_SOURCE,
      /CallNotificationDataModule\.clearCallData\(\)/,
      'logout must retire pending call data, including credentials written by older versions',
    );
    assert.match(
      SESSION_CLEANUP_SOURCE,
      /clearPendingCallActionForSession\(callLaunchGeneration\)/,
      'logout must retire a captured call action before another account can process it',
    );
    assert.match(
      SESSION_CLEANUP_SOURCE,
      /callKitService\.clearPendingNativeState\(\)/,
      'logout must await bounded native CallKit pending-payload cleanup',
    );
  });

  it('does not rehydrate legacy credentials from a stale launch handoff', () => {
    assert.doesNotMatch(
      CALL_LAUNCH_HANDLER_SOURCE,
      /launchIntent\.(?:token|serverUrl)|extras\[['"](?:token|serverUrl)['"]\]/,
      'stale Android launch extras must not be copied into AsyncStorage or call payloads',
    );
    assert.doesNotMatch(
      CALL_DATA_MODULE_SOURCE,
      /\b(?:token|serverUrl)\??\s*:/,
      'the Android native call-data contract must not expose reusable credentials',
    );
  });

  it('invalidates asynchronous call work when the auth session changes', () => {
    assert.match(
      CALL_LAUNCH_HANDLER_SOURCE,
      /getCallLaunchLifecycleGeneration[\s\S]*isCurrentCallLaunchLifecycle/,
      'call actions need a generation boundary tied to auth/session replacement',
    );
    assert.match(
      CALL_LAUNCH_HANDLER_SOURCE,
      /await this\.getInitialIntent\(\);[\s\S]*!isCurrentCallLaunchLifecycle\(generation\)/,
      'a late native launch-intent read must not persist a stale action',
    );
    assert.match(
      CALL_LAUNCH_HANDLER_SOURCE,
      /await AsyncStorage\.getItem\(pendingCallActionKey\(sessionMarker\)\);[\s\S]*!isCurrentCallLaunchLifecycle\(generation\)/,
      'a pending action read must be discarded after logout or account replacement',
    );
    assert.match(
      CALL_LAUNCH_HANDLER_SOURCE,
      /await callService\.joinCall\(\{ callId: payload\.callId \}\);[\s\S]*!isCurrentCallLaunchLifecycle\(generation\)/,
      'late call credentials must not be applied to a replaced session',
    );
    assert.match(
      CALL_LAUNCH_HANDLER_SOURCE,
      /await callService\.declineCall\(launchIntent\.callId\);[\s\S]*!isCurrentCallLaunchLifecycle\(generation\)/,
      'late decline completion must not notify a replaced session',
    );
    assert.match(
      CALL_LAUNCH_HANDLER_SOURCE,
      /clearPendingCallAction\(\): Promise<void> \{[\s\S]*clearPendingCallActionForSession\(getCallLaunchLifecycleGeneration\(\)\)/,
      'logout cleanup must invalidate in-flight work before clearing its persisted action',
    );
    assert.match(
      CALL_LAUNCH_HANDLER_SOURCE,
      /reset\(\): void \{[\s\S]*invalidateCallLaunchSession\(\);[\s\S]*this\.handled = true;/,
      'the synchronous reset path must invalidate in-flight work without blocking auth',
    );
    assert.match(
      CALL_LAUNCH_LIFECYCLE_SOURCE,
      /PENDING_CALL_ACTION_SESSION_MARKER_KEY[\s\S]*cacheMmkv\.getNumber[\s\S]*cacheMmkv\.set/,
      'session replacement must be durable across an app restart when AsyncStorage cleanup fails',
    );
    assert.match(
      CALL_LAUNCH_LIFECYCLE_SOURCE,
      /unavailable marker is not a fresh session[\s\S]*return null;/i,
      'marker read failures must disable pending-action processing instead of selecting :0',
    );
    assert.match(
      CALL_LAUNCH_HANDLER_SOURCE,
      /launchIntent\.sessionMarker !== sessionMarker[\s\S]*this\.handled = true/,
      'actions without the current session marker must fail closed and never notify listeners',
    );
  });

  it('retires native CallKit payloads on session cleanup', () => {
    assert.match(
      CALL_ACTIONS_SESSION_SOURCE,
      /clearNotificationV2CallSession\(\): void[\s\S]*callKitService\.clearSessionState\(\)/,
      'notification session cleanup must retire CallKit payloads on both platforms',
    );
    assert.match(
      CALL_ACTIONS_SESSION_SOURCE,
      /clearNotificationV2CallSession\(\): void[\s\S]*callKitService\.clearPendingNativeState\(\)/,
      'workspace replacement must also retire native pending CallKit payloads',
    );
    assert.match(
      IOS_CALL_KIT_SOURCE,
      /clearSessionState\(\): void[\s\S]*this\.incomingCallPayloads\.clear\(\)[\s\S]*this\.payloadByCallId\.clear\(\)[\s\S]*PendingCallModule\.clearPendingCall/,
      'iOS must clear in-memory and native pending CallKit payloads',
    );
    assert.match(
      ANDROID_CALL_KIT_SOURCE,
      /clearSessionState\(\): void[\s\S]*this\.callPayloads\.clear\(\)[\s\S]*this\.callKeepDisplayedUUIDs\.clear\(\)[\s\S]*this\.answeredUUIDs\.clear\(\)/,
      'Android must clear in-memory CallKit payloads and action state',
    );
    assert.match(
      ANDROID_CALL_KIT_SOURCE,
      /clearSessionState\(\): void[\s\S]*reportEndCallWithUUID[\s\S]*this\.callKeepDisplayedUUIDs\.clear\(\)/,
      'Android must end tracked Telecom calls before discarding teardown bookkeeping',
    );
    assert.match(
      IOS_CALL_KIT_SOURCE,
      /private lifecycleGeneration = 0;[\s\S]*lookupPayload\([\s\S]*generation[\s\S]*generation !== this\.lifecycleGeneration/,
      'iOS native payload lookups must not repopulate state after session cleanup',
    );
    assert.match(
      IOS_CALL_KIT_SOURCE,
      /clearSessionState\(\): void[\s\S]*this\.sessionActive = false[\s\S]*this\.handlers = \{\}/,
      'iOS cleanup must retire handlers as well as payloads',
    );
    assert.match(
      IOS_CALL_KIT_SOURCE,
      /lookupPayload\([\s\S]*generation = this\.lifecycleGeneration[\s\S]*generation !== this\.lifecycleGeneration/,
      'iOS native payload lookups must not repopulate state after session cleanup',
    );
    assert.match(
      CALL_SETUP_SOURCE,
      /const generation = \+\+callSetupGeneration[\s\S]*await setupIncomingCallCategory\(\);[\s\S]*if \(!isCurrentSetup\(\)\) return;[\s\S]*registerCallKitHandlers\(\)/,
      'a stale call-session startup must not re-register handlers after logout',
    );
    assert.match(
      CALL_SETUP_SOURCE,
      /await CallNotificationDataModule\.getCallData\(\);[\s\S]*if \(!isCurrentSetup\(\) \|\| !data\?\.callId\) return;/,
      'a delayed native call-action read must be discarded after logout or account replacement',
    );
    assert.match(
      CALL_SETUP_SOURCE,
      /checkCallNotificationDataWithRetry\([\s\S]*isCurrentSetup: CallSetupGuard[\s\S]*checkCallNotificationData\(isCurrentSetup\)/,
      'retry callbacks must retain the call-session guard across delayed attempts',
    );
    assert.match(
      CALL_ACTIONS_SOURCE,
      /let callSessionGeneration = 0;[\s\S]*clearNotificationV2CallSession\(\): void \{[\s\S]*callSessionGeneration \+= 1;/,
      'logout must invalidate in-flight call accept/decline continuations',
    );
    assert.match(
      CALL_ACTIONS_SOURCE,
      /await callService\.joinCall\(\{ callId: payload\.callId \}\);[\s\S]*if \(expectedGeneration !== callSessionGeneration\) return;[\s\S]*callKitService\.reportCallConnected/,
      'a late join response must not reconnect or navigate an old account session',
    );
  });
});
